import sys
input = sys.stdin.read

def main():
    data = input().split()
    T = 1
    index = 0

    class FastIn:
        def __init__(self, data):
            self.data = data
            self.idx = 0

        def getNext(self):
            val = self.data[self.idx]
            self.idx += 1
            return val

        def getInt(self):
            return int(self.getNext())

        def getLong(self):
            return int(self.getNext())

    class Processor:
        def __init__(self, out, fi):
            self.out = out
            self.fi = fi

        def process(self, all, t):
            n = self.fi.getInt()
            mod = self.fi.getInt()

            dp = [[0] * (n * n + 5) for _ in range(n)]
            dp[0][0] = 1
            for i in range(1, n):
                for j in range(len(dp[0])):
                    for c in range(i + 1):
                        if j - c >= 0:
                            dp[i][j] += dp[i - 1][j - c]
                            dp[i][j] %= mod
                            if dp[i][j] == 0:
                                dp[i][j] += mod

            prefixSum = [[0] * len(dp[0]) for _ in range(n)]
            for i in range(n):
                sum_ = 0
                for j in range(len(dp[0])):
                    sum_ += dp[i][j]
                    sum_ %= mod
                    if sum_ == 0:
                        sum_ += mod
                    prefixSum[i][j] = sum_

            factorial = [1] * 251001
            for i in range(1, len(factorial)):
                factorial[i] = (factorial[i - 1] * i) % mod

            nCr = [[0] * 501 for _ in range(501)]
            nCr[0][0] = 1
            for i in range(1, 501):
                nCr[i][0] = 1
                for j in range(1, i + 1):
                    nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod

            totalRes = 0
            for i in range(n - 1):
                cnt = n - i
                pre = n - cnt
                comb = (nCr[n][pre] * factorial[pre]) % mod
                total = 0
                last = dp[cnt - 2]
                ssum = 0
                totalSum = 0
                for j in range(2, len(dp[0])):
                    total += prefixSum[cnt - 2][j - 2] * (cnt - 1)
                    total %= mod

                    val = last[j] * total
                    totalRes += val
                    totalRes %= mod

                    ssum += prefixSum[cnt - 2][j - 2]
                    if j - cnt - 1 >= 0:
                        ssum -= prefixSum[cnt - 2][j - cnt - 1]
                    ssum %= mod

                    total -= ssum
                    total %= mod

                totalRes += (prefixSum[cnt - 2][0] * comb) % mod
                totalRes %= mod

            print(totalRes)

    fi = FastIn(data)
    out = sys.stdout
    for _ in range(T):
        p = Processor(out, fi)
        p.process(T, 0)

main()

